reply:
I used a single-column `columns` layout as the root, because the catalog has no other container. The hero, feature grid, testimonial and call-to-action button are stacked as blocks inside it. I used `feature_grid` set to three columns for the features.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "landing",
      "catalogId": "https://a2uicatalog.ai/catalog/d-t3.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "landing",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 1,
          "gap": "2.5rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "hero",
                  "component": "gradient_hero",
                  "badge": "New: Lumen 2.0",
                  "title": "Plan smarter. Ship faster.",
                  "subtitle": "Lumen brings your tasks, docs, and team conversations into one calm workspace so projects move forward without the chaos.",
                  "align": "center"
                },
                {
                  "id": "features",
                  "component": "feature_grid",
                  "heading": "Everything your team needs",
                  "description": "Powerful tools that stay out of your way.",
                  "columns": 3,
                  "features": [
                    {
                      "icon": "⚡",
                      "title": "Lightning fast",
                      "description": "Instant search and keyboard-first navigation keep you in flow, even on the largest projects."
                    },
                    {
                      "icon": "🤝",
                      "title": "Built for collaboration",
                      "description": "Comment, assign, and co-edit in real time so everyone stays aligned."
                    },
                    {
                      "icon": "🔒",
                      "title": "Secure by default",
                      "description": "Enterprise-grade encryption and granular permissions protect your work."
                    }
                  ]
                },
                {
                  "id": "testimonial",
                  "component": "testimonial_card",
                  "text": "Lumen replaced three tools for us. Our team ships a week faster every sprint, and nobody misses the old setup.",
                  "author_name": "Priya Raman",
                  "author_title": "VP of Product, Northwind",
                  "rating": 5
                },
                {
                  "id": "cta",
                  "component": "cta_button",
                  "label": "Start your free trial",
                  "url": "https://example.com/signup",
                  "color": "#4f46e5"
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
